-- #174, ADR-0016: keep only the year of birth, never the full date.
-- Generated by Prisma as DROP + ADD; reordered by hand so the year of every
-- existing user survives: add the column, copy the year, then drop the date.

-- AlterTable
ALTER TABLE "user" ADD COLUMN     "birthYear" INTEGER,
ADD COLUMN     "adulthoodConfirmedAt" TIMESTAMP(3);

UPDATE "user" SET "birthYear" = EXTRACT(YEAR FROM "birthDate")::INTEGER WHERE "birthDate" IS NOT NULL;

ALTER TABLE "user" DROP COLUMN "birthDate";

-- The last line of defence for the range the registration and the profile
-- check (OLDEST_BIRTH_YEAR in shared/auth/registration). The upper bound moves
-- with the calendar, so it stays with the application.
ALTER TABLE "user" ADD CONSTRAINT "user_birth_year_range" CHECK ("birthYear" IS NULL OR "birthYear" >= 1900);

-- "adulthoodConfirmedAt" stays NULL for existing users: they never ticked the
-- box, and their 18+ was checked against the full date at sign-up.
